    { id: "eshofcafeelverich", cat: "ye", area: "cevre", title: "Have breakfast or cake at Hofcafé Elverich in Rheinberg",
      desc: "Hofcafé Elverich at Elverich 2A in Rheinberg serves homemade cake, hearty regional dishes, breakfast and brunch.",
      tip: "A good stop on Rhine-side cycling routes.", q: "Hofcafé Elverich, Elverich 2A, Rheinberg", kind: "sweet", src: ["https://freizeitmonster.de/blog/biergaerten-rheinberg"] },
    { id: "esrheinwacht", cat: "ye", area: "cevre", title: "Eat on the Rhine dyke at Café Restaurant Rheinwacht in Voerde",
      desc: "Café Restaurant Rheinwacht at Dammstraße 46 has a riverside beer garden, hearty home-style dishes, homemade cake and minigolf.",
      tip: "Good after a ride on the Rhine cycle path.", q: "Café Restaurant Rheinwacht, Dammstraße 46, Voerde", kind: "meal", src: ["https://freizeitmonster.de/blog/biergaerten-rheinberg"] },
    { id: "esjananderfaehr", cat: "ye", area: "cevre", title: "Cross the Niers by hand-cranked ferry at Jan an de Fähr",
      desc: "Jan an de Fähr in Weeze is a riverside restaurant with a conservatory and large terrace, and a hand-cranked ferry across the Niers behind the building.",
      tip: "Very busy on summer weekends with cyclists.", q: "Jan an de Fähr, Höst-Vornicker-Weg 9, Weeze", kind: "meal", src: ["https://www.komoot.com/highlight/7474850", "https://freizeitmonster.de/blog/deutsche-restaurants-kalkar"] },
    { id: "esschlemmerich", cat: "ye", area: "cevre", title: "Order the Friday fish buffet at Schlemmerich on the Emmerich promenade",
      desc: "Schlemmerich at Rheinpromenade 2 serves German and international dishes and is known for a Friday fish buffet, breakfast and brunch.",
      tip: "Ask for a window or terrace seat facing the Rhine.", q: "Schlemmerich, Rheinpromenade 2, Emmerich am Rhein", kind: "meal", src: ["https://freizeitmonster.de/blog/deutsche-restaurants-kalkar"] },
    { id: "esalteapotheke", cat: "ye", area: "cevre", title: "Dine on Rheinberg's market square at Zur alten Apotheke",
      desc: "Zur alten Apotheke at Großer Markt 12-14 serves steaks and German and regional dishes in the old-town centre of Rheinberg.",
      tip: "Combine with a stroll around the Rheinberg old town.", q: "Zur alten Apotheke, Großer Markt 12-14, Rheinberg", kind: "snack", src: ["https://freizeitmonster.de/blog/biergaerten-rheinberg"] },
    { id: "essuedsee", cat: "dene", area: "cevre", title: "Swim at the Strandbad Xantener Südsee",
      desc: "The Freizeitzentrum Xanten runs the Südsee beach with 1,000 m of fine sand, shallow areas for children, a natural pool and an aqua park. Together the Nord- and Südsee offer 245 ha of water.",
      tip: "Best in summer. Check f-z-x.de for beach hours and prices.", q: "Strandbad Xantener Südsee, Xanten", months: [5, 6, 7, 8, 9], src: ["https://www.seen.de/xantener-suedsee/strandbad-xantener-suedsee/"] },
    { id: "esbeachline", cat: "dene", area: "cevre", title: "Try windsurfing or SUP at Wassersportcenter Beachline",
      desc: "The FZX water-sports centre at the Xanten lakes offers surfing, stand-up paddling, catamaran sailing and diving, with beginner courses.",
      tip: "Book courses in advance for summer.", q: "Wassersportcenter Beachline, Xantener Südsee, Xanten", months: [5, 6, 7, 8, 9], src: ["https://qweb.f-z-x.de/wp-content/uploads/2023/10/PI-Eroeffnung-neues-Wassersportcenter-Beachline-v28072023.pdf"] },
    { id: "eswunderlandkalkar", cat: "dene", area: "cevre", title: "Ride coasters in a never-used nuclear plant at Wunderland Kalkar",
      desc: "Wunderland Kalkar, once Kernie's Familienpark, is a theme park on the grounds of the never-completed Kalkar fast-breeder reactor. The 2026 main season runs from 28 March to early November.",
      tip: "Summer tickets were about 36.50 euro in 2026. See wunderlandkalkar.eu.", q: "Wunderland Kalkar, Griether Straße 110, Kalkar", months: [3, 4, 5, 6, 7, 8, 9, 10, 11], src: ["https://www.freizeitparkdeals.de/parks/kernies-wunderland-kalkar/"] },
    { id: "esirrland", cat: "dene", area: "cevre", title: "Spend a day at the Irrland farm adventure park in Kevelaer",
      desc: "Irrland at Am Scheidweg 1 in Kevelaer-Twisteden is billed as Europe's largest farm adventure park. The 2026 season ran 14 March to 1 November, daily 9-18, with tickets sold online only.",
      tip: "Book tickets online ahead of time.", q: "Irrland, Am Scheidweg 1, Kevelaer", months: [3, 4, 5, 6, 7, 8, 9, 10], src: ["https://www.irrland.de/en/oeffnungszeiten/"] },
    { id: "esreesferry", cat: "dene", area: "cevre", title: "Cross the Rhine on the Rääße Pöntje ferry from Rees",
      desc: "The pedestrian and bicycle ferry runs from Rees to Reeserschanz in Kalkar from Palm Sunday to the end of October, on selected days of the week.",
      tip: "Check niederrheinfaehre.de for the current timetable.", q: "Rheinfähre Rees, Rheinpromenade, Rees", months: [4, 5, 6, 7, 8, 9, 10], src: ["https://de.wikipedia.org/wiki/Rees", "https://www.gps-tour.info/99242"] },
    { id: "esemmerichpromenade", cat: "dene", area: "cevre", title: "Stroll Emmerich's Rhine promenade under the suspension bridge",
      desc: "The Rheinpromenade is a waterfront walk where river cruise ships dock, with views of passing barges and the Emmerich bridge.",
      tip: "Pair with the Rheinmuseum or lunch at Schlemmerich.", q: "Rheinpromenade, Emmerich am Rhein", tags: ["free"], src: ["https://hanse.org/en/tourist/emmerich-am-rhein"] },
    { id: "eskleveparks", cat: "dene", area: "cevre", title: "Walk through Kleve's Forstgarten and Tiergarten parks",
      desc: "The Forstgarten and Tiergarten are landscaped parks of the Kleve garden landscape, with benches, a playground, a bandstand and refreshments. The Neuer Tiergarten axis runs from the amphitheatre to the Prinz-Moritz-Kanal.",
      tip: "A walk starts at the car park on Tiergartenstraße/Wasserburgallee.", q: "Forstgarten, Tiergartenstraße, Kleve", tags: ["free"], src: ["https://www.komoot.com/highlight/237923", "https://eghn.org/en/klever-gartenlandschaft-2"] },
    { id: "eskermisdahl", cat: "dene", area: "cevre", title: "Hike the Kermisdahl route through Kleve's Prinz-Moritz-Park",
      desc: "The 8.7 km Kermisdahl route starts at Café Königsgarten and climbs the Prinz-Moritz-Weg to the Klever Ring.",
      tip: "Mostly easy, with a hill. Details on ich-geh-wandern.de.", q: "Prinz-Moritz-Park, Kleve", tags: ["free"], src: ["https://www.ich-geh-wandern.de/kermisdahl-route-kleve"] },
    { id: "eswildgeese", cat: "dene", area: "cevre", title: "Watch Arctic wild geese on the Lower Rhine",
      desc: "Up to 180,000 Arctic geese winter on the Lower Rhine, arriving in November. NABU offers bus excursions from Kranenburg from mid-November to mid-February, and the Bislicher Insel is another major resting area.",
      tip: "Dress warmly; dawn and dusk are best. Contact the NABU Naturschutzstation Niederrhein.", q: "Bislicher Insel, Xanten", months: [11, 12, 1, 2], tags: ["free"], src: ["https://www.nabu.de/natur-erleben/naturtipps/wintergaeste-aus-dem-hohen-norden"] },
    { id: "espilgrimage", cat: "dene", area: "cevre", title: "Light a candle in Kevelaer's Kerzenkapelle in pilgrimage season",
      desc: "Kevelaer is a major Marian pilgrimage site whose season opens on 1 May. In 2026 it runs 1 May to 30 November, with pilgrim candles and devotions in the Kerzenkapelle daily.",
      tip: "Big pilgrim days such as the Tamil pilgrimage in August are crowded.", q: "Kerzenkapelle, Kapellenplatz, Kevelaer", months: [5, 6, 7, 8, 9, 10, 11], tags: ["free"], src: ["https://www.wallfahrt-kevelaer.de", "https://www.evangelisch.de/inhalte/242334/30-04-2025/kevelaer-eroeffnet-wallfahrtssaison"] },
    { id: "esmoersfestival", cat: "dene", area: "cevre", title: "Hear experimental jazz at the Moers Festival",
      desc: "The Moers Festival began in 1972 as the New Jazz Festival Moers and is held at Pentecost. Since 2021 it has used the Moers city park, and in 2026 it moves to the Kastellplatz.",
      tip: "Held over Pentecost weekend. Check moers-festival.de.", q: "Kastellplatz, Moers", months: [5, 6], src: ["https://de.wikipedia.org/wiki/Moers_Festival"] },
    { id: "eshaldenorddeutschland", cat: "dene", area: "cevre", title: "Climb Halde Norddeutschland in Neukirchen-Vluyn",
      desc: "This 102 m former spoil heap of the Niederberg colliery covers 81 ha and is the flagship of the Landschaftspark NiederRhein. The Himmelstreppe is the most direct climb, with views toward Moers and Duisburg.",
      tip: "Start at the car park on Geldernsche Straße. The loop is around 6.6 km.", q: "Halde Norddeutschland, Geldernsche Straße, Neukirchen-Vluyn", tags: ["free"], src: ["https://www.ich-geh-wandern.de/auf-die-halde-norddeutschland-neukirchen-vluyn", "https://www.ruhr-tourismus.de/en/echt-fotogen/halden-im-ruhrgebiet/halde-norddeutschland/"] },
    { id: "esdaemmerwald", cat: "dene", area: "cevre", title: "Hike the Dämmerwald in Naturpark Hohe Mark near Schermbeck",
      desc: "All of Schermbeck lies in the Naturpark Hohe Mark. The Dämmerwald covers about 1,400 ha, and the Hohe Mark Steig and other long-distance trails pass through.",
      tip: "NRW has designated a wolf area near Schermbeck, so keep dogs on leads.", q: "Dämmerwald, Schermbeck", tags: ["free"], src: ["https://www.ich-geh-wandern.de/durch-den-dämmer-wald-und-den-lichtenhagen-schermbeck"] },
    { id: "esxantenrees", cat: "dene", area: "cevre", title: "Cycle the Xanten to Rees loop along the Rhine",
      desc: "The signed bike route Xanten-Rees-Xanten uses the Rees ferry Rääße Pöntje from Palm Sunday to the end of October.",
      tip: "Check the ferry's operating days before you set out.", q: "Marktplatz, Xanten", tags: ["free"], src: ["https://www.gps-tour.info/99242"] },
    { id: "doeisenbahnmuseum", cat: "gor", area: "cevre", title: "See steam locomotives at the Eisenbahnmuseum Dahlhausen",
      desc: "The Eisenbahnmuseum Bochum-Dahlhausen is a railway museum in a former locomotive depot with steam locomotives and carriages. It is open from March to mid-November.",
      tip: "Open Tuesday to Friday and Sunday in season.", q: "Eisenbahnmuseum Bochum, Dr.-C.-Otto-Straße 191, Bochum", months: [3, 4, 5, 6, 7, 8, 9, 10, 11], src: ["https://maps.adac.de/poi/bochum-dahlhausen-railway-museum-oben-im-eiberg-1-1"] }
